let content = fs.readFileSync(phrasesFilePath, "utf8");
const match = content.match(/export const UNIVERSAL_PHRASES: Record<string, Partial<Record<Language, string>>> = (\{[\s\S]*\});\n$/);
if (!match) {
  console.error("Could not find UNIVERSAL_PHRASES");
  process.exit(1);
}
const existing = eval("(" + match[1] + ")");
const merged = { ...existing, ...GEO_PHRASES };

const newPhrasesCode =
  `import type { Language } from "./languages";\n\n` +
  `export const UNIVERSAL_PHRASES: Record<string, Partial<Record<Language, string>>> = ` +
  JSON.stringify(merged, null, 2) +
  `;\n`;

fs.writeFileSync(phrasesFilePath, newPhrasesCode, "utf8");
console.log("Successfully updated universalPhrases.ts with Geographic & Mining Wording, total keys:", Object.keys(merged).length);
